+    return true;
+  } catch (error) {
+    setConnection("等待服务", false);
+    setMessage(`尚未连接推理服务：${error.message}`, false);
+    return false;
+  }
+}
+
+function drawResult(result) {
+  const context = overlay.getContext("2d");
+  context.clearRect(0, 0, overlay.width, overlay.height);
