+    const [x1, y1, x2, y2] = result.device_bbox;
+    context.strokeStyle = "#2f7df6";
+    context.lineWidth = Math.max(2, overlay.width / 360);
+    context.strokeRect(x1, y1, x2 - x1, y2 - y1);
+  }
+  if (Array.isArray(result.contact_point)) {
+    const [x, y] = result.contact_point;
+    context.fillStyle = "#f04438";
+    context.beginPath();
+    context.arc(x, y, Math.max(5, overlay.width / 130), 0, Math.PI * 2);
+    context.fill();
+    context.strokeStyle = "#ffffff";
+    context.lineWidth = 2;
+    context.stroke();
+  }
+}
+
+function updatePerformance(result) {
+  const timings = result.timings_ms || {};
+  document.querySelector("#device-ms").textContent = timings.device?.toFixed?.(1) ?? timings.device ?? "--";
+  document.querySelector("#contact-ms").textContent = timings.contact?.toFixed?.(1) ?? timings.contact ?? "--";
+  document.querySelector("#total-ms").textContent = timings.total?.toFixed?.(1) ?? timings.total ?? "--";
+  const now = performance.now();
+  if (lastCompletedAt) {
+    const instant = 1000 / Math.max(1, now - lastCompletedAt);
+    smoothedFps = smoothedFps ? smoothedFps * 0.8 + instant * 0.2 : instant;
+    document.querySelector("#actual-fps").textContent = smoothedFps.toFixed(1);
+  }
+  lastCompletedAt = now;
+}
+
+async function sendFrame() {
+  if (!running || requestInFlight || camera.readyState < HTMLMediaElement.HAVE_CURRENT_DATA) return;
+  requestInFlight = true;
