+
+cameraButton.addEventListener("click", async () => {
+  if (running) {
+    stopCamera();
+    return;
+  }
+  try {
+    await startCamera();
+  } catch (error) {
+    stopCamera();
+    setMessage(`无法启动摄像头：${error.message}`, false);
+  }
+});
+
