�from __future__ import annotations

import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SEMVER = re.compile(r"^[0-9]+\.[0-9]+\.[0-9]+$")
SHA256 = re.compile(r"^[a-f0-9]{64}$")


def digest(path: Path) -> str:
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            value.update(chunk)
    return value.hexdigest()


def main() -> int:
    errors: list[str] = []
    warnings: list[str] = []
    version = (ROOT / "VERSION").read_text(encoding="utf-8").strip()
    if not SEMVER.fullmatch(version):
        errors.append(f"invalid VERSION: {version}")
    catalog = (ROOT / "catalog" / "versions.yaml").read_text(encoding="utf-8")
    if f"current_version: {version}" not in catalog:
        errors.append("VERSION and catalog current_version differ")
    if f"  - version: {version}" not in catalog:
        errors.append("current VERSION is absent from versions.yaml")
    for schema in ("frame_result.schema.json", "model_manifest.schema.json"):
        try:
            json.loads((ROOT / "contracts" / schema).read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            errors.append(f"invalid contract {schema}: {exc}")
    for path in sorted((ROOT / "manifests").glob("v5_*_onnx.json")):
        manifest = json.loads(path.read_text(encoding="utf-8"))
        if not SHA256.fullmatch(str(manifest.get("sha256", ""))):
            errors.append(f"invalid sha256 in {path.name}")
        artifact = ROOT / str(manifest.get("artifact_path", ""))
        if artifact.is_file():
            actual = digest(artifact)
            if actual != manifest["sha256"]:
                errors.append(f"artifact SHA256 mismatch: {artifact}")
        else:
            warnings.append(f"artifact not present locally: {artifact}")
    for path in sorted((ROOT / "configs").rglob("*")):
        if path.is_file() and "/home/" in path.read_text(encoding="utf-8", errors="ignore"):
            errors.append(f"machine absolute path in config: {path.relative_to(ROOT)}")
    result = subprocess.run(
        ["git", "-C", str(ROOT.parent), "ls-files", "--", ROOT.name],
        check=False,
        text=True,
        stdout=subprocess.PIPE,
    )
    for relative in result.stdout.splitlines():
        path = ROOT.parent / relative
        if path.is_file() and path.stat().st_size > 25 * 1024 * 1024:
            errors.append(f"large binary tracked by Git: {relative}")
    for warning in warnings:
        print(f"WARNING: {warning}")
    for error in errors:
        print(f"ERROR: {error}", file=sys.stderr)
    print(f"validated version={version}, errors={len(errors)}, warnings={len(warnings)}")
    return 1 if errors else 0


if __name__ == "__main__":
    raise SystemExit(main())

