    "training/contact_v5": ("dev-zero-touch", "96509609817fa0d9e7335746e08f67622a4efee7"),
    "training/experiments": ("dev-zero-touch", "96509609817fa0d9e7335746e08f67622a4efee7"),
    "runtimes/cpp_onnx": ("cpp-http-migration", "e8798373ad89af17f622f10ebc421a74d7a02b2c"),
    "runtimes/rk3568_rknn": ("rk3568-deploy-v1", "e8798373ad89af17f622f10ebc421a74d7a02b2c"),
    "web/rk3568_demo": ("rk3568-deploy-v1", "e8798373ad89af17f622f10ebc421a74d7a02b2c"),
    "runtimes/python_cuda": ("catalog-authored", "31506d33b774504549bd17191c874e2a7bc82286"),
}


def run_git(path: Path, *args: str) -> str:
    result = subprocess.run(
        ["git", "-C", str(path), *args],
        check=False,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
    )
    return result.stdout.rstrip()


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def top_level_sizes(root: Path) -> dict[str, int | None]:
    sizes: dict[str, int | None] = {}
    for path in sorted(root.iterdir(), key=lambda item: item.name.casefold()):
        if path.name in {".git", "目标检测项目整理_2026.9.1"}:
            continue
        result = subprocess.run(
            ["du", "-sb", "--", str(path)],
            check=False,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
        )
        try:
            sizes[path.name] = int(result.stdout.split()[0])
        except (IndexError, ValueError):
            sizes[path.name] = None
    return sizes


def provenance_for(relative: str) -> tuple[str, str]:
    for prefix, provenance in SOURCE_PROVENANCE.items():
        if relative == prefix or relative.startswith(prefix + "/"):
            return provenance
    return "catalog-authored", "31506d33b774504549bd17191c874e2a7bc82286"


def main() -> None:
    snapshot = {
        "captured_at_utc": datetime.now(timezone.utc).isoformat(),
        "repository_root": str(REPOSITORY_ROOT),
        "protected_paths": [
            ".git", ".worktrees", ".venv", "third_party", "data", "datasets",
            "annotations", "models/camera_active_v5",
        ],
        "worktrees": {},
        "git_worktree_list": run_git(REPOSITORY_ROOT, "worktree", "list", "--porcelain"),
        "branches": run_git(REPOSITORY_ROOT, "branch", "--all", "--verbose", "--no-abbrev"),
        "tags": run_git(REPOSITORY_ROOT, "tag", "--list"),
        "top_level_sizes_bytes": top_level_sizes(REPOSITORY_ROOT),
    }
    for name, path in WORKTREES.items():
        if not path.exists():
            snapshot["worktrees"][name] = {"path": str(path), "missing": True}
            continue
        snapshot["worktrees"][name] = {
            "path": str(path),
            "head": run_git(path, "rev-parse", "HEAD"),
            "branch": run_git(path, "branch", "--show-current"),
            "status_porcelain": run_git(path, "status", "--short"),
        }
    (DELIVERY_ROOT / "catalog" / "worktree_snapshot.json").write_text(
        json.dumps(snapshot, ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
    )

    rows: list[dict[str, object]] = []
    for top in ("training", "runtimes", "web", "configs", "contracts", "tools", "tests"):
        root = DELIVERY_ROOT / top
        if not root.exists():
            continue
        for path in sorted(candidate for candidate in root.rglob("*") if candidate.is_file()):
            relative = path.relative_to(DELIVERY_ROOT).as_posix()
            source_worktree, base_commit = provenance_for(relative)
            rows.append({
                "delivery_path": relative,
                "source_worktree": source_worktree,
                "base_commit": base_commit,
                "size_bytes": path.stat().st_size,
                "sha256": sha256(path),
            })
    with (DELIVERY_ROOT / "catalog" / "source_inventory.csv").open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=("delivery_path", "source_worktree", "base_commit", "size_bytes", "sha256"))
        writer.writeheader()
        writer.writerows(rows)


if __name__ == "__main__":
    main()
