�const params = new URLSearchParams(window.location.search);
const apiBase = (params.get("api") || "http://127.0.0.1:8080").replace(/\/$/, "");
const camera = document.querySelector("#camera");
const capture = document.querySelector("#capture");
const overlay = document.querySelector("#overlay");
const empty = document.querySelector("#camera-empty");
const cameraButton = document.querySelector("#camera-button");
const resetButton = document.querySelector("#reset-button");
const message = document.querySelector("#message");
const connection = document.querySelector(".connection");
const connectionLabel = document.querySelector("#connection-label");

let mediaStream = null;
let requestInFlight = false;
let running = false;
let frameId = 0;
let lastCompletedAt = 0;
let smoothedFps = 0;

function setMessage(text, healthy = false) {
  message.querySelector("span").textContent = text;
  message.classList.toggle("is-healthy", healthy);
}

function setConnection(text, healthy = false) {
  connectionLabel.textContent = text;
  connection.classList.toggle("is-healthy", healthy);
}

function updateMetadata(payload) {
  document.querySelector("#software-version").textContent = payload.software_version || "--";
  document.querySelector("#runtime-provider").textContent = payload.runtime_provider || "--";
  document.querySelector("#model-lineage").textContent = payload.model_lineage || "--";
}

async function checkHealth() {
  try {
    const response = await fetch(`${apiBase}/health`, { cache: "no-store" });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const health = await response.json();
    updateMetadata(health);
    setConnection("服务已连接", true);
    setMessage(`已连接 ${health.runtime_provider || "推理服务"}`, true);
    return true;
  } catch (error) {
    setConnection("等待服务", false);
    setMessage(`尚未连接推理服务：${error.message}`, false);
    return false;
  }
}

function drawResult(result) {
  const context = overlay.getContext("2d");
  context.clearRect(0, 0, overlay.width, overlay.height);
  if (Array.isArray(result.device_bbox)) {
    const [x1, y1, x2, y2] = result.device_bbox;
    context.strokeStyle = "#2f7df6";
    context.lineWidth = Math.max(2, overlay.width / 360);
    context.strokeRect(x1, y1, x2 - x1, y2 - y1);
  }
  if (Array.isArray(result.contact_point)) {
    const [x, y] = result.contact_point;
    context.fillStyle = "#f04438";
    context.beginPath();
    context.arc(x, y, Math.max(5, overlay.width / 130), 0, Math.PI * 2);
    context.fill();
    context.strokeStyle = "#ffffff";
    context.lineWidth = 2;
    context.stroke();
  }
}

function updatePerformance(result) {
  const timings = result.timings_ms || {};
  document.querySelector("#device-ms").textContent = timings.device?.toFixed?.(1) ?? timings.device ?? "--";
  document.querySelector("#contact-ms").textContent = timings.contact?.toFixed?.(1) ?? timings.contact ?? "--";
  document.querySelector("#total-ms").textContent = timings.total?.toFixed?.(1) ?? timings.total ?? "--";
  const now = performance.now();
  if (lastCompletedAt) {
    const instant = 1000 / Math.max(1, now - lastCompletedAt);
    smoothedFps = smoothedFps ? smoothedFps * 0.8 + instant * 0.2 : instant;
    document.querySelector("#actual-fps").textContent = smoothedFps.toFixed(1);
  }
  lastCompletedAt = now;
}

async function sendFrame() {
  if (!running || requestInFlight || camera.readyState < HTMLMediaElement.HAVE_CURRENT_DATA) return;
  requestInFlight = true;
  capture.width = camera.videoWidth;
  capture.height = camera.videoHeight;
  overlay.width = camera.videoWidth;
  overlay.height = camera.videoHeight;
  capture.getContext("2d").drawImage(camera, 0, 0);
  const blob = await new Promise((resolve) => capture.toBlob(resolve, "image/jpeg", 0.7));
  try {
    const response = await fetch(`${apiBase}/v1/stream/frame`, {
      method: "POST",
      headers: {
        "Content-Type": "image/jpeg",
        "X-Frame-Id": String(frameId++),
        "X-Timestamp-Ms": String(Date.now()),
      },
      body: blob,
    });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const result = await response.json();
    updateMetadata(result);
    updatePerformance(result);
    drawResult(result);
    setConnection("服务已连接", true);
    setMessage(result.device_bbox ? "检测正常" : "画面中未检测到设备", true);
  } catch (error) {
    setConnection("连接中断", false);
    setMessage(`推理请求失败：${error.message}`, false);
  } finally {
    requestInFlight = false;
  }
}

function frameLoop() {
  if (!running) return;
  sendFrame().finally(() => window.setTimeout(frameLoop, 16));
}

async function startCamera() {
  await checkHealth();
  mediaStream = await navigator.mediaDevices.getUserMedia({
    video: { width: { ideal: 960 }, height: { ideal: 540 }, facingMode: "user" },
    audio: false,
  });
  camera.srcObject = mediaStream;
  await camera.play();
  running = true;
  empty.hidden = true;
  cameraButton.querySelector("span").textContent = "停止摄像头";
  frameLoop();
}

function stopCamera() {
  running = false;
  mediaStream?.getTracks().forEach((track) => track.stop());
  mediaStream = null;
  camera.srcObject = null;
  overlay.getContext("2d").clearRect(0, 0, overlay.width, overlay.height);
  empty.hidden = false;
  cameraButton.querySelector("span").textContent = "启动摄像头";
}

cameraButton.addEventListener("click", async () => {
  if (running) {
    stopCamera();
    return;
  }
  try {
    await startCamera();
  } catch (error) {
    stopCamera();
    setMessage(`无法启动摄像头：${error.message}`, false);
  }
});

resetButton.addEventListener("click", async () => {
  try {
    const response = await fetch(`${apiBase}/v1/stream/reset`, { method: "POST" });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    frameId = 0;
    smoothedFps = 0;
    lastCompletedAt = 0;
    drawResult({});
    setMessage("状态已重置", true);
  } catch (error) {
    setMessage(`重置失败：${error.message}`, false);
  }
});

