�from __future__ import annotations

import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SEMVER = re.compile(r"^[0-9]+\.[0-9]+\.[0-9]+$")
SHA256 = re.compile(r"^[a-f0-9]{64}$")
FORBIDDEN_TOP_LEVEL = ("runtimes", "catalog", "contracts", "manifests", "artifacts", "dist", "configs")


def digest(path: Path) -> str:
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            value.update(chunk)
    return value.hexdigest()


def main() -> int:
    errors: list[str] = []
    warnings: list[str] = []
    version = (ROOT / "VERSION").read_text(encoding="utf-8").strip()
    if not SEMVER.fullmatch(version):
        errors.append(f"invalid VERSION: {version}")

    catalog = (ROOT / "docs" / "versions.yaml").read_text(encoding="utf-8")
    if f"current_version: {version}" not in catalog or f"  - version: {version}" not in catalog:
        errors.append("VERSION and docs/versions.yaml differ")

    pyproject = (ROOT / "pyproject.toml").read_text(encoding="utf-8")
    if f'version = "{version}"' not in pyproject:
        errors.append("VERSION and pyproject.toml differ")
    for forbidden in ("celery", "redis", "oss2"):
        if re.search(rf'^\s*"{forbidden}(?:[<=>\[]|\")', pyproject, re.MULTILINE | re.IGNORECASE):
            errors.append(f"unexpected cloud dependency: {forbidden}")

    lock_path = ROOT / "uv.lock"
    if not lock_path.is_file():
        errors.append("missing uv.lock")
    else:
        lock_text = lock_path.read_text(encoding="utf-8")
        if 'name = "target-detection"' not in lock_text:
            errors.append("uv.lock does not contain target-detection")

    readme = (ROOT / "README.md").read_text(encoding="utf-8")
    for required_text in ("只提交", "交付文件夹/target-detection-0.0.1", "uv sync --frozen"):
        if required_text not in readme:
            errors.append(f"README missing delivery instruction: {required_text}")

    version_source = (ROOT / "src" / "target_detection" / "version.py").read_text(encoding="utf-8")
    if f'SOFTWARE_VERSION = "{version}"' not in version_source:
        errors.append("VERSION and source version differ")

    for schema in ("frame_result.schema.json", "model_manifest.schema.json"):
        try:
            json.loads((ROOT / "schemas" / schema).read_text(encoding="utf-8"))
        except (OSError, ValueError) as exc:
            errors.append(f"invalid schema {schema}: {exc}")

    for role in ("device", "contact"):
        manifest_path = ROOT / "models" / role / "manifest.json"
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        if not SHA256.fullmatch(str(manifest.get("sha256", ""))):
            errors.append(f"invalid SHA256 in {manifest_path.relative_to(ROOT)}")
        artifact = ROOT / str(manifest.get("artifact_path", ""))
        if artifact.is_file():
            if digest(artifact) != manifest["sha256"]:
                errors.append(f"artifact SHA256 mismatch: {artifact.relative_to(ROOT)}")
        else:
            warnings.append(f"artifact not present locally: {artifact.relative_to(ROOT)}")

    for path in sorted((ROOT / "config").rglob("*")):
        if path.is_file():
            text = path.read_text(encoding="utf-8", errors="ignore")
            if "/home/" in text or re.search(r"[A-Za-z]:\\", text):
                errors.append(f"machine absolute path in config: {path.relative_to(ROOT)}")

    for name in FORBIDDEN_TOP_LEVEL:
        if (ROOT / name).exists():
            errors.append(f"obsolete top-level directory remains: {name}")

    result = subprocess.run(
        ["git", "-C", str(ROOT.parent), "ls-files", "--", ROOT.name],
        check=False,
        text=True,
        stdout=subprocess.PIPE,
    )
    for relative in result.stdout.splitlines():
        path = ROOT.parent / relative
        if path.is_file() and path.stat().st_size > 25 * 1024 * 1024:
            errors.append(f"large binary tracked by Git: {relative}")

    delivery = ROOT / "交付文件夹" / f"target-detection-{version}"
    if delivery.is_dir():
        verify = subprocess.run([sys.executable, str(delivery / "verify.py")], check=False)
        if verify.returncode:
            errors.append("generated delivery folder verification failed")

    for warning in warnings:
        print(f"WARNING: {warning}")
    for error in errors:
        print(f"ERROR: {error}", file=sys.stderr)
    print(f"validated version={version}, errors={len(errors)}, warnings={len(warnings)}")
    return 1 if errors else 0


if __name__ == "__main__":
    raise SystemExit(main())
from __future__ import annotations

import hashlib
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE if (HERE / "VERSION").is_file() else HERE.parent


def digest(path: Path) -> str:
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            value.update(chunk)
    return value.hexdigest()


def main() -> int:
    errors: list[str] = []
    for required in ("README.md", "CHANGELOG.md", "uv.lock"):
        if not (ROOT / required).is_file():
            errors.append(f"missing required delivery file: {required}")
    sums = ROOT / "SHA256SUMS"
    if not sums.is_file():
        raise FileNotFoundError(sums)
    for line in sums.read_text(encoding="utf-8").splitlines():
        expected, relative = line.split("  ", 1)
        path = ROOT / relative
        if not path.is_file():
            errors.append(f"missing: {relative}")
        elif digest(path) != expected:
            errors.append(f"SHA256 mismatch: {relative}")

    version = (ROOT / "VERSION").read_text(encoding="utf-8").strip()
    release = json.loads((ROOT / "release_manifest.json").read_text(encoding="utf-8"))
    if release.get("software_version") != version:
        errors.append("VERSION differs from release_manifest.json")
    if release.get("cloud_worker_included") is not False:
        errors.append("unexpected cloud worker in local delivery")
    for role in ("device", "contact"):
        manifest = json.loads((ROOT / "models" / role / "manifest.json").read_text(encoding="utf-8"))
        model = ROOT / "models" / role / "model.onnx"
        if digest(model) != manifest.get("sha256"):
            errors.append(f"model manifest mismatch: {role}")

    for error in errors:
        print(f"ERROR: {error}")
    print(f"verified delivery version={version}, errors={len(errors)}")
    return 1 if errors else 0


if __name__ == "__main__":
    raise SystemExit(main())

